"""Consistent JSON error handling.

Every error response has the shape:

    {"error": {"code": "<machine_code>", "message": "<human message>",
               "details": {...}}}
"""
from flask import jsonify
from werkzeug.exceptions import HTTPException


class APIError(Exception):
    status_code = 500
    code = "internal_error"

    def __init__(self, message=None, *, code=None, status_code=None, details=None):
        super().__init__(message)
        self.message = message or self.__class__.__name__
        if code:
            self.code = code
        if status_code:
            self.status_code = status_code
        self.details = details or {}


class ValidationError(APIError):
    status_code = 400
    code = "validation_error"


class AuthError(APIError):
    status_code = 401
    code = "unauthorized"


class ForbiddenError(APIError):
    status_code = 403
    code = "forbidden"


class NotFoundError(APIError):
    status_code = 404
    code = "not_found"


class ConflictError(APIError):
    status_code = 409
    code = "conflict"


class RateLimitError(APIError):
    status_code = 429
    code = "rate_limited"

    def __init__(self, message="Rate limit exceeded", *, retry_after=None, **kw):
        super().__init__(message, **kw)
        self.retry_after = retry_after


def _error_body(code, message, details=None):
    return {"error": {"code": code, "message": message, "details": details or {}}}


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(err: APIError):
        resp = jsonify(_error_body(err.code, err.message, err.details))
        resp.status_code = err.status_code
        if isinstance(err, RateLimitError) and err.retry_after is not None:
            resp.headers["Retry-After"] = str(err.retry_after)
        return resp

    @app.errorhandler(HTTPException)
    def handle_http_error(err: HTTPException):
        code = {
            400: "bad_request",
            401: "unauthorized",
            403: "forbidden",
            404: "not_found",
            405: "method_not_allowed",
            415: "unsupported_media_type",
        }.get(err.code, "http_error")
        resp = jsonify(_error_body(code, err.description))
        resp.status_code = err.code or 500
        return resp

    @app.errorhandler(Exception)
    def handle_unexpected(err: Exception):
        app.logger.exception("Unhandled exception")
        resp = jsonify(_error_body("internal_error", "An unexpected error occurred"))
        resp.status_code = 500
        return resp

"""Lightweight declarative input validation.

A schema is a dict of field name -> spec dict. Supported spec keys:

    type       python type (str, int, bool, ...)
    required   bool (default False)
    min_length / max_length   for strings
    min / max                 for numbers
    pattern    compiled regex or regex string (full match)
    choices    iterable of allowed values
    strip      strip whitespace on strings (default True)

`validate(data, schema)` returns the cleaned payload or raises
ValidationError with a per-field `details` dict.
"""
import re

from flask import request

from .errors import ValidationError

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def json_body():
    """Return the request JSON body or raise a ValidationError."""
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        raise ValidationError("Request body must be a JSON object")
    return data


def validate(data, schema):
    errors = {}
    cleaned = {}

    unknown = set(data) - set(schema)
    for field in unknown:
        errors[field] = "unknown field"

    for field, spec in schema.items():
        required = spec.get("required", False)
        if field not in data or data[field] is None:
            if required:
                errors[field] = "this field is required"
            continue

        value = data[field]
        ftype = spec.get("type")

        # bool is a subclass of int; reject bools for int fields explicitly.
        if ftype is int and isinstance(value, bool):
            errors[field] = "must be of type int"
            continue
        if ftype is not None and not isinstance(value, ftype):
            errors[field] = f"must be of type {ftype.__name__}"
            continue

        if isinstance(value, str) and spec.get("strip", True):
            value = value.strip()

        if isinstance(value, str):
            if required and not value:
                errors[field] = "must not be empty"
                continue
            if "min_length" in spec and len(value) < spec["min_length"]:
                errors[field] = f"must be at least {spec['min_length']} characters"
                continue
            if "max_length" in spec and len(value) > spec["max_length"]:
                errors[field] = f"must be at most {spec['max_length']} characters"
                continue
            pattern = spec.get("pattern")
            if pattern is not None:
                if isinstance(pattern, str):
                    pattern = re.compile(pattern)
                if not pattern.fullmatch(value):
                    errors[field] = spec.get("pattern_message", "invalid format")
                    continue

        if isinstance(value, (int, float)) and not isinstance(value, bool):
            if "min" in spec and value < spec["min"]:
                errors[field] = f"must be >= {spec['min']}"
                continue
            if "max" in spec and value > spec["max"]:
                errors[field] = f"must be <= {spec['max']}"
                continue

        if "choices" in spec and value not in spec["choices"]:
            errors[field] = f"must be one of: {', '.join(map(str, spec['choices']))}"
            continue

        cleaned[field] = value

    if errors:
        raise ValidationError("Invalid input", details=errors)
    return cleaned

"""Offset/limit pagination helpers for SQL-backed list endpoints."""
import math

from flask import current_app, request, url_for

from .errors import ValidationError


def page_args():
    """Parse and validate ?page= and ?per_page= query params."""
    cfg = current_app.config
    default_per = cfg["PAGINATION_DEFAULT_PER_PAGE"]
    max_per = cfg["PAGINATION_MAX_PER_PAGE"]

    try:
        page = int(request.args.get("page", 1))
        per_page = int(request.args.get("per_page", default_per))
    except (TypeError, ValueError):
        raise ValidationError("page and per_page must be integers")

    if page < 1:
        raise ValidationError("page must be >= 1")
    if per_page < 1 or per_page > max_per:
        raise ValidationError(f"per_page must be between 1 and {max_per}")
    return page, per_page


def paginated_response(items, total, page, per_page, endpoint, **url_kwargs):
    """Build a standard paginated envelope with navigation links."""
    pages = max(1, math.ceil(total / per_page)) if total else 1

    def link(p):
        return url_for(endpoint, page=p, per_page=per_page, **url_kwargs)

    return {
        "data": items,
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "pages": pages,
        },
        "links": {
            "self": link(page),
            "first": link(1),
            "last": link(pages),
            "next": link(page + 1) if page < pages else None,
            "prev": link(page - 1) if page > 1 else None,
        },
    }

